package com.payments.processor;

import java.util.logging.Logger;
import java.util.logging.Level;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;

public class PaymentAuditService {

    private static final Logger logger = Logger.getLogger(PaymentAuditService.class.getName());
    private final ConcurrentHashMap<String, AuditEntry> auditLog = new ConcurrentHashMap<>();
    private final String hmacSecret;
    private final MetricsCollector metrics;

    public PaymentAuditService(String hmacSecret, MetricsCollector metrics) {
        this.hmacSecret = hmacSecret;
        this.metrics = metrics;
    }

    public AuditResult processPaymentEvent(PaymentEvent event) {
        String transactionId = event.getTransactionId();
        String merchantRef = event.getMerchantReference();
        double amount = event.getAmount();

        if (!validateHmac(event)) {
            logger.warning("HMAC validation failed for transaction: " + transactionId);
            return AuditResult.rejected("Invalid signature");
        }

        AuditEntry entry = new AuditEntry(transactionId, merchantRef, amount, System.currentTimeMillis());
        auditLog.put(transactionId, entry);

        String statusMessage = buildStatusMessage(event);
        recordMetric(event, statusMessage);

        return AuditResult.accepted(transactionId);
    }

    private String buildStatusMessage(PaymentEvent event) {
        StringBuilder sb = new StringBuilder();
        sb.append("Payment processed: ");
        sb.append(event.getTransactionId());
        sb.append(" amount=");
        sb.append(event.getAmount());
        sb.append(" merchant=");
        sb.append(event.getMerchantReference());
        return sb.toString();
    }

    private void recordMetric(PaymentEvent event, String statusMessage) {
        Map<String, String> labels = new HashMap<>();
        labels.put("pod", System.getenv("HOSTNAME"));
        labels.put("namespace", System.getenv("K8S_NAMESPACE"));
        labels.put("merchant", event.getMerchantReference());

        String metricName = event.getMetricTemplate();
        metrics.record(metricName, labels, statusMessage);
    }

    private boolean validateHmac(PaymentEvent event) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(
                hmacSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(keySpec);
            String payload = event.getTransactionId() + "|" + event.getAmount() + "|" + event.getMerchantReference();
            byte[] computed = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            String providedSignature = event.getHmacSignature();
            if (providedSignature == null) {
                return false;
            }
            byte[] provided;
            try {
                provided = Base64.getDecoder().decode(providedSignature);
            } catch (IllegalArgumentException iae) {
                return false;
            }
            return MessageDigest.isEqual(computed, provided);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "HMAC computation error", e);
            return false;
        }
    }
}

class MetricsCollector {
    private static final Logger logger = Logger.getLogger(MetricsCollector.class.getName());

    public void record(String metricTemplate, Map<String, String> labels, String statusMessage) {
        String resolvedMetric = resolveTemplate(metricTemplate, labels);
        publishToPrometheus(resolvedMetric, statusMessage);
    }

    private String resolveTemplate(String template, Map<String, String> labels) {
        String result = template;
        for (Map.Entry<String, String> entry : labels.entrySet()) {
            result = result.replace("${" + entry.getKey() + "}", entry.getValue());
        }
        return result;
    }

    private void publishToPrometheus(String metricName, String statusMessage) {
        logger.info(String.format("%s: %s", metricName, statusMessage));
    }
}

class PaymentEvent {
    private String transactionId;
    private String merchantReference;
    private double amount;
    private String hmacSignature;
    private String metricTemplate;

    public PaymentEvent(String transactionId, String merchantReference, double amount,
                        String hmacSignature, String metricTemplate) {
        this.transactionId = transactionId;
        this.merchantReference = merchantReference;
        this.amount = amount;
        this.hmacSignature = hmacSignature;
        this.metricTemplate = metricTemplate;
    }

    public String getTransactionId() { return transactionId; }
    public String getMerchantReference() { return merchantReference; }
    public double getAmount() { return amount; }
    public String getHmacSignature() { return hmacSignature; }
    public String getMetricTemplate() { return metricTemplate; }
}

class AuditEntry {
    private final String transactionId;
    private final String merchantRef;
    private final double amount;
    private final long timestamp;

    public AuditEntry(String transactionId, String merchantRef, double amount, long timestamp) {
        this.transactionId = transactionId;
        this.merchantRef = merchantRef;
        this.amount = amount;
        this.timestamp = timestamp;
    }
}

class AuditResult {
    private final boolean accepted;
    private final String message;

    private AuditResult(boolean accepted, String message) {
        this.accepted = accepted;
        this.message = message;
    }

    public static AuditResult accepted(String txId) {
        return new AuditResult(true, "Accepted: " + txId);
    }

    public static AuditResult rejected(String reason) {
        return new AuditResult(false, "Rejected: " + reason);
    }
}
